//! Excluded actual-gallery custom Rust temporal text and picker workflows.
#[path = "../../examples/gallery/custom_temporal_formats.rs"]
mod gallery_formats;
use dioxus::prelude::*;
use dioxus_ix::*;

#[component]
pub fn CustomTemporalFormatsPreview() -> Element {
    #[cfg(all(feature = "desktop", not(target_arch = "wasm32")))]
    let window = dioxus::desktop::window();
    rsx! {
        style { {STYLES} }
        IxTheme { class:"custom-temporal-formats-review",
            gallery_formats::CustomTemporalFormatsExample {}
            div { onmounted:move |_| {
                #[cfg(all(feature="desktop",not(target_arch="wasm32")))]
                {let window=window.clone();spawn(async move {
                    let query=crate::dom_query::eval(NATIVE_TEMPORAL_TEXT_CHECK);let _=query.send("temporaltext");
                    match query.join::<serde_json::Value>().await {
                        Ok(value)if value["ok"]==true=>{println!("Dioxus native Temporal text: {value}");window.close();}
                        value=>{eprintln!("Dioxus native Temporal text failed: {value:?}");std::process::exit(1);}
                    }
                });spawn(async move {futures_timer::Delay::new(std::time::Duration::from_secs(40)).await;eprintln!("Temporal text native replay timed out");std::process::exit(1);});}
            } }
        }
    }
}
const STYLES: &str = "body{margin:0}.custom-temporal-formats-review{box-sizing:border-box;min-height:100vh;padding:24px}@media(max-width:600px){.custom-temporal-formats-review{padding:16px}}";

